"""Low level user interaction functions for the SIM KV PANEL LAT POS pane in the SimDialogs test tool app.
Used by the SimDialogs page object class"""

from .objects.sim_dialogs_objects import SimDialogsObjects
from . import sim_dialog_main_functions as SimDialogMainFuncs
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import SIMDIALOGS_APP_NAME


@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def check_sim_kv_panel_lat_pos_node_online_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the Node Online Checkbox only if its enabled and unchecked
    """
    sim_kv_panel_lat_pos_node_online_checkbox = SimDialogMainFuncs.locate_checkbox_per_pane_by_index_and_id(childObjIndex=2, checkBoxId="246")
    if not CommonActions.get_checkbox_state(sim_kv_panel_lat_pos_node_online_checkbox):
        CommonActions.left_click_object_no_move(sim_kv_panel_lat_pos_node_online_checkbox)


@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def uncheck_sim_kv_panel_lat_pos_node_online_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the Node Online Checkbox only if its enabled and checked
    """
    sim_kv_panel_lat_pos_node_online_checkbox = SimDialogMainFuncs.locate_checkbox_per_pane_by_index_and_id(childObjIndex=2, checkBoxId="246")
    if CommonActions.get_checkbox_state(sim_kv_panel_lat_pos_node_online_checkbox):
        CommonActions.left_click_object_no_move(sim_kv_panel_lat_pos_node_online_checkbox)

