@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def get_sim_kv_panel_lateral_position_textfield() -> str:
    """Locates the main Sim Dialogs window > then reads the data in the Sim KV lateral position textfield only if the object exists
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window():
        text_value = CommonActions.get_uneditable_field_objects_text_value(SimDialogsObjects.sim_KV_Panel_Lat_Pos_field)
        if text_value is not None:
            return text_value
    return ""

